pub fn equality_derived_runtime_field_value(a: Rc<RuntimeFieldValue>, b: Rc<RuntimeFieldValue>) -> bool {
    ((a.field.clone() == b.field.clone()) && equality_derived_runtime_value(a.value.clone(), b.value.clone()))
}

pub fn equality_derived_evaluation_environment(a: Rc<EvaluationEnvironment>, b: Rc<EvaluationEnvironment>) -> bool {
    crate::std_algebra::map_values_eq(a.bindings.clone(), b.bindings.clone(), |eqp0, eqq0| equality_derived_runtime_value(eqp0.clone(), eqq0.clone()))
}

pub fn equality_derived_runtime_primitive_value(a: Rc<RuntimePrimitiveValue>, b: Rc<RuntimePrimitiveValue>) -> bool {
    (crate::v2_std_node::node_equal_ignoring_provenance(a.primitive_type.clone(), b.primitive_type.clone()) && (a.bytes.clone() == b.bytes.clone()))
}

pub fn equality_derived_runtime_aggregate_value(a: Rc<RuntimeAggregateValue>, b: Rc<RuntimeAggregateValue>) -> bool {
    (crate::v2_std_node::node_equal_ignoring_provenance(a.aggregate_type.clone(), b.aggregate_type.clone()) && crate::std_algebra::zip_eq(a.fields.clone(), b.fields.clone(), |eqp0, eqq0| equality_derived_runtime_field_value(eqp0.clone(), eqq0.clone())))
}

