pub fn equality_derived_resource_effect_boundary(a: Rc<ResourceEffectBoundary>, b: Rc<ResourceEffectBoundary>) -> bool {
    ((((equality_derived_boundary_allowance(a.ffi.clone(), b.ffi.clone()) && equality_derived_boundary_allowance(a.exceptions.clone(), b.exceptions.clone())) && equality_derived_boundary_allowance(a.async_.clone(), b.async_.clone())) && equality_derived_boundary_allowance(a.concurrency.clone(), b.concurrency.clone())) && equality_derived_boundary_allowance(a.identity_reference.clone(), b.identity_reference.clone()))
}

pub fn equality_derived_operation_call(a: Rc<OperationCall>, b: Rc<OperationCall>) -> bool {
    ((((a.kind.clone() == b.kind.clone()) && crate::v2_std_model_core::equality_derived_primitive_operation_ref(a.operation.clone(), b.operation.clone())) && crate::std_algebra::zip_eq(a.arguments.clone(), b.arguments.clone(), |eqp0, eqq0| equality_derived_runtime_value(eqp0.clone(), eqq0.clone()))) && equality_derived_evaluation_frame(a.continuation.clone(), b.continuation.clone()))
}

